#![allow(clippy::excessive_precision)]
#![allow(dead_code)]
//
// Two test binaries read this module and each uses a different subset of the
// constants, so the unused half warns in whichever one is being built.
//
// R emits seventeen significant digits. Trimming them by hand would mean
// editing generated values, so the lint is turned off for this file only.

//! Bulk differential expression parity fixtures, generated against edgeR 4.8.2,
//! limma 3.66.0 and R 4.5.1.
//!
//! DO NOT EDIT. Regenerate with `Rscript dev/gen_edger_fixtures.R` and paste
//! the output below.
//!
//! The counts come from a Numerical Recipes LCG seeded at 20260101, reduced
//! modulo a per-gene, per-group bound. Every step is exact in a double, so the
//! Rust side rebuilds the identical integer matrix and no float data crosses as
//! text. Two hundred genes over eight samples in two groups of four; every
//! fortieth gene is low enough that `filterByExpr` drops it and every seventh
//! is three times higher in the second group.
//!
//! The `VOOM_*` and `TREND_*` constants run the same counts and design through
//! `voomLmFit` and limma-trend respectively, on the same already-filtered and
//! TMM-normalised `DGEList`.

/// Genes in the fixture.
pub const N_GENES: usize = 200;

/// Samples in the fixture.
pub const N_SAMPLES: usize = 8;

/// Design columns: an intercept and the group.
pub const N_COEF: usize = 2;

/// Seed for the fixture LCG.
pub const LCG_SEED: u64 = 20260101;

/// Rebuilds the count matrix the R side used.
///
/// ### Returns
///
/// The counts, gene-major and row-major, `N_GENES * N_SAMPLES`.
pub fn counts() -> Vec<f64> {
    let mut state: u64 = LCG_SEED;
    let mut next = || {
        state = (1664525u64.wrapping_mul(state).wrapping_add(1013904223)) % 4294967296;
        state
    };

    let mut out = Vec::with_capacity(N_GENES * N_SAMPLES);
    for gene in 0..N_GENES {
        for sample in 0..N_SAMPLES {
            let group = sample / (N_SAMPLES / 2);
            let base = 3 + (gene % 40) * 5;
            let modulus = if group == 1 && gene % 7 == 0 {
                base * 3
            } else {
                base
            };
            out.push((next() % modulus as u64) as f64);
        }
    }
    out
}

/// The design, row-major `N_SAMPLES * N_COEF`.
///
/// ### Returns
///
/// An intercept column and a zero-one group column.
pub fn design() -> Vec<f64> {
    (0..N_SAMPLES)
        .flat_map(|s| [1.0, (s / (N_SAMPLES / 2)) as f64])
        .collect()
}

